package org.bukkit;
public enum ChatColor { BLACK('0'),DARK_BLUE('1'),DARK_GREEN('2'),DARK_AQUA('3'),DARK_RED('4'),DARK_PURPLE('5'),GOLD('6'),GRAY('7'),DARK_GRAY('8'),BLUE('9'),GREEN('a'),AQUA('b'),RED('c'),LIGHT_PURPLE('d'),YELLOW('e'),WHITE('f'),MAGIC('k'),BOLD('l'),STRIKETHROUGH('m'),UNDERLINE('n'),ITALIC('o'),RESET('r');private final char code;ChatColor(char c){code=c;}public char getChar(){return code;}public String toString(){return "§"+code;}public static String translateAlternateColorCodes(char alt,String s){char[] a=s.toCharArray();for(int i=0;i+1<a.length;i++)if(a[i]==alt&&"0123456789abcdefklmnorABCDEFKLMNOR".indexOf(a[i+1])>=0){a[i]='§';a[i+1]=Character.toLowerCase(a[i+1]);}return new String(a);}public static String stripColor(String s){return s==null?null:s.replaceAll("§[0-9a-fk-orA-FK-OR]","");}}
